Definition isSome {A} (o : option A) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 2 "S01<scd;$A;R{cd;$o;R!1+^?#1-^?RN$o;R!1+^?#2+^@#12$a;R#2,^A,^B").
Definition has := CC.has_cell.
Definition leaf_chk (i : nat) (c : CC.cutpoint) (k : nat) (ps : SR.post_spec) (t : CC.tag) : bool :=
  match t with
  | CC.TGoto j _ => (* [comment removed for export] *)
      ((Nat.eqb i 1 || Nat.eqb i 2) && (Nat.eqb j 2 || Nat.eqb j 3) && CHA.foot_chk GT.NF G.HDECL c BLK [] && CH2.blocks_eqb (nth i G.BLS []) BLK)%bool
  | CC.TOther pc =>
      match CH2.ret_of G.RETS i k with
      | Some j =>
          match nth_error G.CPS j with
          | Some cj =>
              if Z.eqb pc PC_ANN then
                (Z.eqb (SR.ps_pc ps) PC_ANN && ((Nat.eqb i 3 && Nat.eqb j 4) || (Nat.eqb i 4 && Nat.eqb j 5)) && CH2.blocks_eqb (nth i G.BLS []) BLK && CH2.blocks_eqb (nth j G.BLS []) BLK
                 && CHA.foot_chk GT.NF G.HDECL c BLK []
                 && isSome (CHA.custom_chk GT.NF G.HDECL GT.SCELLS GT.GLO GT.GHI 4096 0 BLK [] WSH STAT None c ps cj BLK [] BLK [])
                 && CL.ps_reg_is ps 10 bE && CL.ps_reg_is ps 11 (EAlu Instr.ALU_ADD bE capE) && CL.ps_reg_is ps 12 (omE i) && CL.ps_reg_is ps 13 (nmE i))%bool
              else if Z.eqb pc PC_OPDEL then
                (Z.eqb (SR.ps_pc ps) PC_OPDEL && Nat.eqb i 5 && Nat.eqb j 6 && CH2.blocks_eqb (nth i G.BLS []) BLK && CH2.blocks_eqb (nth j G.BLS []) []
                 && CHA.foot_chk GT.NF G.HDECL c BLK []
                 && isSome (CHA.custom_chk GT.NF G.HDECL GT.SCELLS GT.GLO GT.GHI 4096 0 [] [] [] NEWS4 None c ps cj BLK [] [] [])
                 && CL.ps_reg_is ps 10 bE)%bool
              else false
          | None => false
          end
      | None =>
          (Z.eqb pc RETPC && CBA.exit_base_chk GT.NF RETPC c ps && CHA.foot_chk GT.NF G.HDECL c [] [] && (Nat.eqb i 0 || Nat.eqb i 6) && CH2.blocks_eqb (nth i G.BLS []) [])%bool
      end
  end.
